class CalendarUtil {

    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        this.events.remove(event)
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for e in this.events {
            if e.date.toLocalDate() == date.toLocalDate() {
                result.add(e)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for e in this.events {
            if (start_time < e.end_time) && (e.start_time < end_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let all_day_start = date.with(hour: 0, minute: 0, second: 0)
        let all_day_end = all_day_start.plusDays(1)
        let events_on_date = this.get_events(date).sortedBy(func (e) { e.start_time })
        let available_slots = ArrayList<(DateTime, DateTime)>()
        var current_start = all_day_start

        for e in events_on_date {
            if current_start < e.start_time {
                available_slots.add((current_start, e.start_time))
            }
            current_start = e.end_time
        }

        if current_start < all_day_end {
            available_slots.add((current_start, all_day_end))
        }

        return available_slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = this.events.filter(func (e) { e.start_time >= now }).sortedBy(func (e) { e.start_time })
        return upcoming.slice(0, num_events.toInt())
    }
}

import std.collection.HashMap

class CamelCaseMap {

    /*
    This is a custom class that allows keys to be in camel case style by converting them from underscore style, which provides dictionary-like functionality.
    */

    let _data: HashMap<String, Any>

    public init() {
        /*
        Initialize data to an empty dictionary
        */
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        /*
        Return the value corresponding to the key
        :param key:String
        :return:Any,the value corresponding to the key
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__getitem__('first_name')
        'John'
        */
        let camelKey = CamelCaseMap._to_camel_case(key)
        return _data.get(camelKey) ?? nil
    }

    public func __setitem__(key: String, value: Any): Unit {
        /*
        Set the value corresponding to the key to the specified value
        :param key:String
        :param value:Any, the specified value
        :return:Unit
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__setitem__('first_name', 'new name')
        >>> camelize_map.__getitem__('first_name')
        'new name'
        */
        let camelKey = CamelCaseMap._to_camel_case(key)
        _data.put(camelKey, value)
    }

    public func __delitem__(key: String): Unit {
        /*
        Delete the value corresponding to the key
        :param key:String
        :return:Unit
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__delitem__('first_name')
        >>> flag = camelize_map._data.contains(camelize_map.to_camel_case('first_name'))
        flag = false
        */
        let camelKey = CamelCaseMap._to_camel_case(key)
        _data.remove(camelKey)
    }

    public func __len__(): Int64 {
        /*
        Returns the length of the own data
        :return:Int64, length of data
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__setitem__('last_name', 'Doe')
        >>> camelize_map.__setitem__('age', 30)
        >>> camelize_map.__len__()
        3
        */
        return _data.size()
    }

    public func _convert_key(key: Any): Any {
        /*
        convert key string into camel case
        If key is not String type, return key directly
        :param key:Any
        :return:Any, converted key string
        >>> camelize_map = CamelCaseMap()
        >>> (camelize_map._convert_key('first_name') as String) ?? ""
        'firstName'
        >>> (camelize_map._convert_key(123) as Int64) ?? 0
        123
        */
        if key is String {
            return CamelCaseMap._to_camel_case(key as String)
        }
        return key
    }

    public static func _to_camel_case(key: String): String {
        /*
        convert key string into camel case
        :param key:String
        :return:String, converted key string
        >>> CamelCaseMap._to_camel_case('first_name')
        'firstName'
        */
        if key.length() == 0 {
            return key
        }
        var result = ""
        var toUpper = false
        for i in 0..key.length() {
            let c = key[i]
            if c == '_' {
                toUpper = true
            } else {
                if toUpper {
                    result += c.upper()
                    toUpper = false
                } else {
                    if result.length() == 0 {
                        result += c.lower()
                    } else {
                        result += c
                    }
                }
            }
        }
        return result
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {

    /*
    This is a class that uses the Chandrasekhar's Sieve method to find all prime numbers within the range
    */

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        /*
        Initialize the ChandrasekharSieve class with the given limit.
        :param n: Int64, the upper limit for generating prime numbers
        */
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        /*
        Generate prime numbers up to the specified limit using the Chandrasekhar sieve algorithm.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.generate_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        if n < 2 {
            return ArrayList<Int64>()
        }

        let sieve: ArrayList<Bool> = ArrayList<Bool>()
        for i in 0..n + 1 {
            sieve.append(true)
        }
        sieve.set(0, false)
        if n >= 1 {
            sieve.set(1, false)
        }

        for i in 2..Int64.sqrt(n) + 1 {
            if sieve.get(i) {
                for j in i * i..n + 1 step i {
                    sieve.set(j, false)
                }
            }
        }

        let result: ArrayList<Int64> = ArrayList<Int64>()
        for i in 2..n + 1 {
            if sieve.get(i) {
                result.append(i)
            }
        }

        return result
    }

    public func get_primes(): ArrayList<Int64> {
        /*
        Get the list of generated prime numbers.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.get_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        return this.primes
    }
}

