class Classroom {

    let id: Int64
    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        for c in this.courses {
            if c == course {
                return
            }
        }
        this.courses.append(course)
    }

    public func remove_course(course: Course): Unit {
        let index = 0
        for c in this.courses {
            if c == course {
                this.courses.remove_at(index)
                return
            }
            index += 1
        }
    }

    private func parse_time(time_str: String): DateTime {
        return DateTime.parse(time_str, "yyyy/MM/dd HH:mm")
    }

    public func is_free_at(check_time: String): Bool {
        let check_dt = this.parse_time(check_time)
        for course in this.courses {
            let start_dt = this.parse_time(course.start_time)
            let end_dt = this.parse_time(course.end_time)
            if check_dt >= start_dt && check_dt <= end_dt {
                return false
            }
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        let new_start = this.parse_time(new_course.start_time)
        let new_end = this.parse_time(new_course.end_time)
        for course in this.courses {
            let start_dt = this.parse_time(course.start_time)
            let end_dt = this.parse_time(course.end_time)
            if new_start < end_dt && new_end > start_dt {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        let name = student.get("name")
        let major = student.get("major")
        for s in this.students {
            if s.get("name") == name {
                return 0
            }
        }
        this.students.add(student)
        this.students_registration_classes.put(name, ArrayList<String>())
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if !this.students_registration_classes.contains(student_name) {
            return ArrayList<String>()
        }
        let classes = this.students_registration_classes.get(student_name)
        if !classes.contains(class_name) {
            classes.add(class_name)
        }
        return classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let result = ArrayList<String>()
        for student in this.students {
            if student.get("major") == major {
                result.add(student.get("name"))
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        let majors = ArrayList<String>()
        for student in this.students {
            let major = student.get("major")
            if !majors.contains(major) {
                majors.add(major)
            }
        }
        return majors
    }

    public func get_most_popular_class_in_major(major: String): String {
        let major_students = this.get_students_by_major(major)
        if major_students.size() == 0 {
            return ""
        }
        let class_count = HashMap<String, Int64>()
        let max_count = 0
        let most_popular_class = ""
        for name in major_students {
            if this.students_registration_classes.contains(name) {
                let classes = this.students_registration_classes.get(name)
                for class_name in classes {
                    let count = class_count.get(class_name, 0) + 1
                    class_count.put(class_name, count)
                    if count > max_count {
                        max_count = count
                        most_popular_class = class_name
                    }
                }
            }
        }
        return most_popular_class
    }
}

import std.collection.ArrayList

class CombinationCalculator {

    /*
    This is a class that provides methods to calculate the number of combinations for a specific count, calculate all possible combinations, and generate combinations with a specified number of elements.
    */

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        /*
        Initialize the calculator with a list of data.
        */
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        /*
        Calculate the factorial of a number.
        :param n: The number to calculate the factorial of,Int64.
        :return: The factorial of the number,Int64.
        */
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        /*
        Calculate the number of combinations for a specific count.
        :param n: The total number of elements,Int64.
        :param m: The number of elements in each combination,Int64.
        :return: The number of combinations,Int64.
        >>> CombinationCalculator.count(4, 2)
        6
        */
        if m > n || m < 0 {
            return 0
        }
        if m == 0 || m == n {
            return 1
        }
        var result = 1
        var m_effective = m
        if m > n - m {
            m_effective = n - m
        }
        for i in 1..m_effective + 1 {
            result *= (n - i + 1)
            result /= i
        }
        return result
    }

    public static func count_all(n: Int64): Int64 {
        /*
        Calculate the number of all possible combinations.
        :param n: The total number of elements,Int64.
        :return: The number of all possible combinations,Int64,if the number of combinations is greater than 2^63-1,return Int64.Max.
        >>> CombinationCalculator.count_all(4)
        15
        */
        if n <= 0 {
            return 0
        }
        let total = (1 << n) - 1
        if total < 0 {
            return Int64.Max
        }
        return total
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        /*
        Generate combinations with a specified number of elements.
        :param m: The number of elements in each combination,Int64.
        :return: A list of combinations,ArrayList<ArrayList<String>>.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> calc.select(2)
        [['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D']]

        */
        let result = ArrayList<ArrayList<String>>()
        if m < 0 || m > datas.size() {
            return result
        }
        if m == 0 {
            result.append(ArrayList<String>())
            return result
        }
        let resultList = ArrayList<String>(Array<String>(m, repeat: ""))
        this._select(0, resultList, 0, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        /*
        Generate all possible combinations of selecting elements from the given data list,and it uses the select method.
        :return: A list of combinations,ArrayList<ArrayList<String>>.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> calc.select_all()
        [['A'], ['B'], ['C'], ['D'], ['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D'], ['A', 'B', 'C'], ['A', 'B', 'D'], ['A', 'C', 'D'], ['B', 'C', 'D'], ['A', 'B', 'C', 'D']]

        */
        let result = ArrayList<ArrayList<String>>()
        let n = datas.size()
        for i in 1..n + 1 {
            let partial = this.select(i)
            for comb in partial {
                result.append(comb)
            }
        }
        return result
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        /*
        Generate combinations with a specified number of elements by recursion.
        :param dataIndex: The index of the data to be selected,Int64.
        :param resultList: The list of elements in the combination,ArrayList<String>.
        :param resultIndex: The index of the element in the combination,Int64.
        :param result: The list of combinations,ArrayList<ArrayList<String>>.
        :return: Unit.
        >>> calc = CombinationCalculator(ArrayList<String>(["A", "B", "C", "D"]))
        >>> result = ArrayList<ArrayList<String>>()
        >>> calc._select(0, ArrayList<String>(Array<String>(2, repeat: "")), 0, result)
        >>> result
        [['A', 'B'], ['A', 'C'], ['A', 'D'], ['B', 'C'], ['B', 'D'], ['C', 'D']]

        */
        if resultIndex == resultList.size() {
            result.append(ArrayList<String>(resultList))
            return
        }
        if dataIndex >= datas.size() {
            return
        }
        for i in dataIndex..datas.size() {
            resultList.set(resultIndex, datas.get(i))
            this._select(i + 1, resultList, resultIndex + 1, result)
        }
    }
}

