class PageUtil {

    let data: ArrayList<Int64>
    let page_size: Int64
    let total_items: Int64
    let total_pages: Int64

    public init(data: ArrayList<Int64>, page_size: Int64) {
        this.data = data
        this.page_size = page_size
        this.total_items = data.size
        this.total_pages = (this.total_items + page_size - 1) / page_size
    }

    public func get_page(page_number: Int64): ArrayList<Int64> {
        if page_number < 1 || page_number > this.total_pages {
            return ArrayList<Int64>()
        }
        let start_index = (page_number - 1) * this.page_size
        let end_index = start_index + this.page_size
        if end_index > this.total_items {
            end_index = this.total_items
        }
        let result = ArrayList<Int64>()
        for i in Range(start_index, end_index) {
            result.append(this.data[i])
        }
        return result
    }

    public func get_page_info(page_number: Int64): Option<PageInfo> {
        if page_number < 1 || page_number > this.total_pages {
            return Option<PageInfo>.none()
        }
        let page_data = this.get_page(page_number)
        let has_previous = page_number > 1
        let has_next = page_number < this.total_pages
        let page_info = PageInfo(page_number, this.page_size, this.total_pages, this.total_items, has_previous, has_next, page_data)
        return Option<PageInfo>.some(page_info)
    }

    public func search(keyword: String): SearchInfo {
        let filtered_data = ArrayList<Int64>()
        for item in this.data {
            if item.to_string().contains(keyword) {
                filtered_data.append(item)
            }
        }
        let total_results = filtered_data.size
        let search_pages = (total_results + this.page_size - 1) / this.page_size
        return SearchInfo(keyword, total_results, search_pages, filtered_data)
    }
}

class PersonRequest {

    /*
    This class validates input personal information data and sets invalid fields to None based to specific rules.
    */

    let name: Option<String>
    let sex: Option<String>
    let phoneNumber: Option<String>

    public init(name: String, sex: String, phoneNumber: String) {
        /*
        Initialize PersonRequest object with the provided information.
        :param name: Option<String>, the name of the person
        :param sex: Option<String>, the sex of the person
        :param phoneNumber: Option<String>, the phone number of the person
        */
        this.name = _validate_name(name) 
        this.sex = _validate_sex(sex)
        this.phoneNumber = _validate_phoneNumber(phoneNumber)
    }

    public static func _validate_name(name: String): Option<String> {
        /*
        Validate the name and return it. If name is empty or exceeds 33 characters in length, set to None.
        :param name: String, the name to validate
        :return: Option<String>, the validated name or None if invalid
        */
        if name.length == 0 || name.length > 33 {
            return None
        }
        return Some(name)
    }

    public static func _validate_sex(sex: String): Option<String> {
        /*
        Validate the sex and return it. If sex is not Man, Woman, or UGM, set to None.
        :param sex: String, the sex to validate
        :return: Option<String>, the validated sex or None if invalid
        */
        let validSexes = ["Man", "Woman", "UGM"]
        for valid in validSexes {
            if sex == valid {
                return Some(sex)
            }
        }
        return None
    }

    public static func _validate_phoneNumber(phoneNumber: String): Option<String> {
        /*
        Validate the phone number and return it. If phoneNumber is empty or not an 11 digit number, set to None.
        :param phoneNumber: String, the phone number to validate
        :return: Option<String>, the validated phone number or None if invalid
        */
        if phoneNumber.length != 11 {
            return None
        }
        for i in 0..phoneNumber.length {
            let c = phoneNumber[i]
            if c < '0' || c > '9' {
                return None
            }
        }
        return Some(phoneNumber)
    }
}

import std.collection.ArrayList

class PushBoxGame {

    /*
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    */

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        /*
        Initialize the push box game with the map and various attributes.
        :param map: ArrayList<ArrayList<String>>, the map of the push box game, represented as a list of strings. 
            Each character on the map represents a different element, including the following:
            - '#' represents a wall that neither the player nor the box can pass through;
            - 'O' represents the initial position of the player;
            - 'G' represents the target position;
            - 'X' represents the initial position of the box.
        >>> map = ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])
        >>> game = PushBoxGame(map) 
        */
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            /*
            Initialize the game by setting the positions of the player, targets, and boxes based on the map.
            >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
            >>> game.targets
            [[3, 3]]
            >>> game.boxes
            [[2, 2]]
            >>> game.player_row
            1
            >>> game.player_col
            1
            */
            for i in 0..this.map.size() {
                let row = this.map.get(i)
                for j in 0..row.size() {
                    let cell = row.get(j)
                    match cell {
                        "O" => {
                            this.player_row = i
                            this.player_col = j
                        },
                        "G" => {
                            let target = ArrayList<Int64>()
                            target.add(i)
                            target.add(j)
                            this.targets.add(target)
                            this.target_count += 1
                        },
                        "X" => {
                            let box = ArrayList<Int64>()
                            box.add(i)
                            box.add(j)
                            this.boxes.add(box)
                        },
                        _ => {}
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        /*
        Check if the game is won. The game is won when all the boxes are placed on target positions.
        And update the value of this.is_game_over.
        :return this.is_game_over: true if all the boxes are placed on target positions, or false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
        >>> game.check_win()
        false
        */
        var matched = 0
        for box in this.boxes {
            let box_row = box.get(0)
            let box_col = box.get(1)
            for target in this.targets {
                let target_row = target.get(0)
                let target_col = target.get(1)
                if box_row == target_row && box_col == target_col {
                    matched += 1
                    break
                }
            }
        }
        this.is_game_over = (matched == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        /*
        Move the player based on the specified direction and check if the game is won.
        :param direction: String, the direction of the player's movement. 
            It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.

        :return: true if the game is won, false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])]))       
        >>> game.print_map()
        # # # # # 
        # O     #
        #   X   #
        #     G #
        # # # # #
        >>> game.move('d')
        false
        >>> game.move('s')   
        false
        >>> game.move('a')   
        false
        >>> game.move('s') 
        false
        >>> game.move('d') 
        true
        */
        var d_row = 0
        var d_col = 0
        match direction {
            "w" => { d_row = -1 },
            "s" => { d_row = 1 },
            "a" => { d_col = -1 },
            "d" => { d_col = 1 },
            _ => { return this.check_win() }
        }

        let new_row = this.player_row + d_row
        let new_col = this.player_col + d_col
        let new_next_row = new_row + d_row
        let new_next_col = new_col + d_col

        if new_row < 0 || new_row >= this.map.size() || new_col < 0 || new_col >= this.map.get(0).size() {
            return this.check_win()
        }

        if this.map.get(new_row).get(new_col) == "#" {
            return this.check_win()
        }

        var box_moved = false
        for box in this.boxes {
            if box.get(0) == new_row && box.get(1) == new_col {
                if new_next_row < 0 || new_next_row >= this.map.size() || new_next_col < 0 || new_next_col >= this.map.get(0).size() {
                    return this.check_win()
                }
                if this.map.get(new_next_row).get(new_next_col) == "#" {
                    return this.check_win()
                }
                for other_box in this.boxes {
                    if other_box.get(0) == new_next_row && other_box.get(1) == new_next_col {
                        return this.check_win()
                    }
                }
                box.set(0, new_next_row)
                box.set(1, new_next_col)
                box_moved = true
                break
            }
        }

        this.player_row = new_row
        this.player_col = new_col
        return this.check_win()
    }

    public func print_map() {
        for row in this.map {
            var line = ""
            for j in 0..row.size() {
                var cell = " "
                var is_box = false
                var is_player = false
                var is_target = false

                for target in this.targets {
                    if target.get(0) == this.map.index_of(row) && target.get(1) == j {
                        is_target = true
                        break
                    }
                }

                for box in this.boxes {
                    if box.get(0) == this.map.index_of(row) && box.get(1) == j {
                        is_box = true
                        break
                    }
                }

                if this.player_row == this.map.index_of(row) && this.player_col == j {
                    is_player = true
                }

                if is_player {
                    cell = "O"
                } else if is_box {
                    cell = "X"
                } else if is_target {
                    cell = "G"
                } else {
                    cell = row.get(j)
                    if cell != "#" {
                        cell = " "
                    }
                }
                line += cell + " "
            }
            print(line.strip_trailing())
        }
    }
}

import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let regex = Regex::new(pattern)
        return regex.is_match(text)
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let regex = Regex::new(pattern)
        let matches = regex.find_all(text)
        let result = ArrayList<String>::new()
        for match in matches {
            result.add(match.get_value())
        }
        return result
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let regex = Regex::new(pattern)
        return regex.split(text)
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let regex = Regex::new(pattern)
        return regex.replace_all(text, replacement)
    }

    public func generate_email_pattern(): String {
        return #'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'#
    }

    public func generate_phone_number_pattern(): String {
        return #'\b\d{3}-\d{3}-\d{4}\b'#
    }

    public func generate_split_sentences_pattern(): String {
        return #'[.!?][\s]{1,2}(?=[A-Z])'#
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = self.generate_split_sentences_pattern()
        let regex = Regex::new(pattern)
        let parts = regex.split(text)
        let result = ArrayList<String>::new()
        for i in 0..parts.size() {
            let part = parts.get(i).strip()
            if i < parts.size() - 1 && part != "" {
                result.add(part)
            } else if i == parts.size() - 1 && text.ends_with(".") || text.ends_with("!") || text.ends_with("?") {
                result.add(part)
            } else if i == parts.size() - 1 {
                result.add(part)
            }
        }
        return result
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = self.generate_phone_number_pattern()
        let regex = Regex::new(pattern)
        return regex.is_match(phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = self.generate_email_pattern()
        return self.findall(pattern, text)
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class Server {

    /*
    This is a class as a server, which handles a white list, message sending and receiving, and information display.
    */

    let white_list: ArrayList<Int64>
    let send_struct: HashMap<String, Any>
    let receive_struct: HashMap<String, Any>

    public init() {
        /*
        Initialize the whitelist as an empty list, and initialize the sending and receiving information as an empty map.
        */
        this.white_list = ArrayList<Int64>()
        this.send_struct = HashMap<String, Any>()
        this.receive_struct = HashMap<String, Any>()
    }

    public func add_white_list(addr: Int64): Option<ArrayList<Int64>> {
        /*
        Add an address to the whitelist and do nothing if it already exists
        :param addr: Int64, address to be added
        :return: new whitelist, return None if the address already exists
        >>> server = Server()
        >>> server.add_white_list(88)
        [88]
        */
        if this.white_list.contains(addr) {
            return Option.None<ArrayList<Int64>>()
        }
        this.white_list.append(addr)
        return Option.Some(this.white_list)
    }

    public func del_white_list(addr: Int64): Option<ArrayList<Int64>> {
        /*
        Remove an address from the whitelist and do nothing if it does not exist
        :param addr: Int64, address to be deleted
        :return: new whitelist, return None if the address does not exist
        >>> server.add_white_list(88)
        >>> server.del_white_list(88)
        []
        */
        let index = this.white_list.index_of(addr)
        if index == -1 {
            return Option.None<ArrayList<Int64>>()
        }
        this.white_list.remove_at(index)
        return Option.Some(this.white_list)
    }

    public func recv(info: HashMap<String, Any>): Any {
        /*
        Receive information containing address and content. If the address is on the whitelist, receive the content; otherwise, do not receive it
        :param info: HashMap<String, Any>, information dictionary containing address and content
        :return: if successfully received, return the content of the information; otherwise, return false
        >>> server.recv(HashMap<String, Any>([("addr",88),("content","abc")]))
        abc
        */
        if !info.contains_key("addr") || !info.contains_key("content") {
            return false
        }
        let addr = info["addr"] as Int64
        if this.white_list.contains(addr) {
            this.receive_struct = info
            return info["content"]
        }
        return false
    }

    public func send(info: HashMap<String, Any>): Option<String> {
        /*
        Send information containing address and content
        :param info: HashMap<String, Any>, information dictionary containing address and content
        :return: if successfully sent, return None; otherwise, return "info structure is not correct"
        >>> server.send(HashMap<String, Any>([("addr",66),("content","ABC")]))
        None
        this.send_struct = HashMap<String, Any>([("addr",66),("content","ABC")])
        */
        if !info.contains_key("addr") || !info.contains_key("content") {
            return Option.Some("info structure is not correct")
        }
        this.send_struct = info
        return Option.None<String>()
    }

    public func show(type_struct: String): Option<HashMap<String, Any>> {
        /*
        Returns struct of the specified type
        :param type: String, the type of struct to be returned, which can be 'send' or 'receive'
        :return: if type is equal to 'send' or 'receive', return the corresponding struct; otherwise, return None
        >>> server.recv(HashMap<String, Any>([("addr",88),("content","abc")]))
        >>> server.send(HashMap<String, Any>([("addr",66),("content","ABC")]))
        >>> server.show("send")
        {"addr":66,"content":"ABC"}
        */
        if type_struct == "send" {
            return Option.Some(this.send_struct)
        } else if type_struct == "receive" {
            return Option.Some(this.receive_struct)
        } else {
            return Option.None<HashMap<String, Any>>()
        }
    }
}

import std.collection.HashMap
import std.math.abs

class Item <: Equatable<Item> {

    var price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Item): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Item): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class ShoppingCart {

    let items: HashMap<String, Item>

    public init() {
        items = HashMap<String, Item>()
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        if items.contains(item) {
            let current_item = items.get(item)!
            items.put(item, Item(current_item.price, current_item.quantity + quantity))
        } else {
            items.put(item, Item(price, quantity))
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        if items.contains(item) {
            let current_item = items.get(item)!
            let new_quantity = current_item.quantity - quantity
            if new_quantity <= 0 {
                items.remove(item)
            } else {
                items.put(item, Item(current_item.price, new_quantity))
            }
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var total: Float64 = 0.0
        for (name, item) in items.pairs() {
            total += item.price * item.quantity
        }
        return total
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SignInSystem {

    /*
    This is a class as sigin in system, including adding users, signing in/out, checking sign-in status, and retrieving signed-in/not signed-in users.
    */

    let users: HashMap<String, Bool>

    public init() {
        /*
        Initialize the sign-in system.
        */
        users = HashMap<String, Bool>()
    }

    public func add_user(username: String): Bool {
        /*
        Add a user to the sign-in system if the user wasn't in the this.users.
        And the initial state is false.
        :param username: String, the username to be added.
        :return: Bool, true if the user is added successfully, false if the user already exists.
        >>> signInSystem.add_user("mike")
        true
        >>> signInSystem.add_user("mike")
        false
        */
        if users.contains(username) {
            return false
        }
        users.put(username, false)
        return true
    }

    public func sign_in(username: String): Bool {
        /*
        Sign in a user if the user was in the this.users and change the state to true.
        :param username: String, the username to be signed in.
        :return: Bool, true if the user is signed in successfully, false if the user does not exist.
        >>> signInSystem.sign_in("mike")
        true
        >>> signInSystem.sign_in("mik")
        false
        */
        if !users.contains(username) {
            return false
        }
        users.put(username, true)
        return true
    }

    public func check_sign_in(username: String): Bool {
        /*
        Check if a user is signed in.
        :param username: String, the username to be checked.
        :return: Bool, true if the user is signed in, false if the user does not exist or is not signed in.
        >>> signInSystem.check_sign_in("jack")
        false
        >>> signInSystem.add_user("jack")
        >>> signInSystem.check_sign_in("jack")
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.check_sign_in("jack")
        true
        */
        if !users.contains(username) {
            return false
        }
        return users.get(username)
    }

    public func all_signed_in(): Bool {
        /*
        Check if all users are signed in.
        :return: Bool, true if all users are signed in, false otherwise.
        >>> signInSystem.add_user("jack")
        true
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.all_signed_in()
        true
        */
        for user in users.keys() {
            if !users.get(user) {
                return false
            }
        }
        return true
    }

    public func all_not_signed_in(): ArrayList<String> {
        /*
        Get a list of usernames that are not signed in.
        :return: ArrayList<String>, a list of usernames that are not signed in.
        >>> signInSystem = SignInSystem()
        >>> signInSystem.add_user("a")
        true
        >>> signInSystem.add_user("b")
        true
        >>> signInSystem.all_not_signed_in()
        ['a', 'b']
        */
        let result = ArrayList<String>()
        for user in users.keys() {
            if !users.get(user) {
                result.add(user)
            }
        }
        return result
    }
}

import std.collection.ArrayList
import std.random.Random

class Snake {

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions.get(0)
        let new_x = head.get(0) + direction.get(0) * this.BLOCK_SIZE
        let new_y = head.get(1) + direction.get(1) * this.BLOCK_SIZE
        let new_head = ArrayList<Int64>([new_x, new_y])

        if new_x == this.food_position.get(0) && new_y == this.food_position.get(1) {
            this.eat_food()
        } else {
            this.positions.insert(0, new_head)
            this.positions.pop_back()
        }

        for i in 1..this.positions.size() {
            let part = this.positions.get(i)
            if new_x == part.get(0) && new_y == part.get(1) {
                this.reset()
                return
            }
        }
    }

    public func random_food_position(): Unit {
        let rand = Random()
        let valid = false
        while !valid {
            let x = rand.randint(0, (this.SCREEN_WIDTH / this.BLOCK_SIZE) - 1) * this.BLOCK_SIZE
            let y = rand.randint(0, (this.SCREEN_HEIGHT / this.BLOCK_SIZE) - 1) * this.BLOCK_SIZE
            this.food_position = ArrayList<Int64>([x, y])
            let on_snake = false
            for pos in this.positions {
                if pos.get(0) == x && pos.get(1) == y {
                    on_snake = true
                    break
                }
            }
            if !on_snake {
                break
            }
        }
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length = this.length + 1
        this.score = this.score + 100
        this.positions.insert(0, ArrayList<Int64>([
            this.food_position.get(0),
            this.food_position.get(1)
        ]))
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    /*
    The class allows to split sentences, count words in a sentence, and process a text file to find the maximum word count.
    */

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let regex = Regex("((?<!Mr)(?<!Mrs)(?<!Dr)(?<!Prof)\\.|\\?)(?=\\s)")
        let parts = regex.split(sentences_string.trim())
        let sentences = ArrayList<String>()
        for part in parts {
            let trimmed = part.trim()
            if trimmed != "" {
                if trimmed.endsWith(".") || trimmed.endsWith("?") {
                    sentences.append(trimmed)
                } else {
                    sentences.append(trimmed + (trimmed.contains("?") ? "?" : "."))
                }
            }
        }
        return sentences
    }

    public func count_words(sentence: String): Int64 {
        let cleaned = sentence.replaceAll("[^\\p{L}\\s]", "")
        let words = cleaned.trim().split("\\s+")
        if words.size() == 1 && words.get(0) == "" {
            return 0
        }
        return words.size()
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = self.split_sentences(sentences_string)
        var max_words = Int64(0)
        for sentence in sentences {
            let word_count = self.count_words(sentence)
            if word_count > max_words {
                max_words = word_count
            }
        }
        return max_words
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class SQLGenerator {

    /*
    This class generates SQL statements for common operations on a table, such as SELECT, INSERT, UPDATE, and DELETE.
    */

    let table_name: String

    public init(table_name: String) {
        /*
        Initialize the table name.
        :param table_name: String
        */
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        /*
        Generates a SELECT SQL statement based on the specified fields and conditions.
        :param fields: Option<ArrayList<String>>, optional. Default is None. The list of fields to be queried.
        :param condition: Option<String>, optional. Default is None. The condition expression for the query.
        :return: String. The generated SQL statement.
        >>> sql = SQLGenerator("table1")
        >>> sql.select(fields: ArrayList<String>(["field1", "field2"]), condition: "filed3 = value1")
        'SELECT field1, field2 FROM table1 WHERE filed3 = value1;'
        */
        let field_list = match fields {
            Some(f) => f.join(", "),
            None => "*"
        }
        let where_clause = match condition {
            Some(c) => " WHERE " + c,
            None => ""
        }
        return "SELECT " + field_list + " FROM " + this.table_name + where_clause + ";"
    }

    public func insert(data: HashMap<String, String>): String {
        /*
        Generates an INSERT SQL statement based on the given data.
        :param data: HashMap<String, String>. The data to be inserted, in dictionary form where keys are field names and values are field values.
        :return: String. The generated SQL statement.
        >>> sql.insert(HashMap<String, String>([('key1', 'value1'), ('key2', 'value2')]))
        "INSERT INTO table1 (key1, key2) VALUES ('value1', 'value2');"
        */
        let keys = ArrayList<String>()
        let values = ArrayList<String>()
        for (k, v) in data {
            keys.add(k)
            values.add("'" + v + "'")
        }
        return "INSERT INTO " + this.table_name + " (" + keys.join(", ") + ") VALUES (" + values.join(", ") + ");"
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        /*
        Generates an UPDATE SQL statement based on the given data and condition.
        :param data: HashMap<String, String>. The data to be updated, in dictionary form where keys are field names and values are new field values.
        :param condition: String. The condition expression for the update.
        :return: String. The generated SQL statement.
        >>> sql.update(HashMap<String, String>([('field1', 'new_value1'), ('field2', 'new_value2')]), "field3 = value1")
        "UPDATE table1 SET field1 = 'new_value1', field2 = 'new_value2' WHERE field3 = value1;"
        */
        let set_parts = ArrayList<String>()
        for (k, v) in data {
            set_parts.add(k + " = '" + v + "'")
        }
        return "UPDATE " + this.table_name + " SET " + set_parts.join(", ") + " WHERE " + condition + ";"
    }

    public func delete(condition: String): String {
        /*
        Generates a DELETE SQL statement based on the given condition.
        :param condition: String. The condition expression for the delete.
        :return: String. The generated SQL statement.
        >>> sql.delete("field1 = value1")
        'DELETE FROM table1 WHERE field1 = value1;'
        */
        return "DELETE FROM " + this.table_name + " WHERE " + condition + ";"
    }

    public func select_female_under_age(age: Int64): String {
        /*
        Generates a SQL statement to select females under a specified age.
        :param age: Int64. The specified age.
        :return: String. The generated SQL statement.
        >>> sql.select_female_under_age(30)
        "SELECT * FROM table1 WHERE age < 30 AND gender = 'female';"
        */
        return "SELECT * FROM " + this.table_name + " WHERE age < " + age.to_string() + " AND gender = 'female';"
    }

    public func select_by_age_range(min_age: Int64, max_age: Int64): String {
        /*
        Generates a SQL statement to select records within a specified age range.
        :param min_age: Int64. The minimum age.
        :param max_age: Int64. The maximum age.
        :return: String. The generated SQL statement.
        >>> sql.select_by_age_range(20, 30)
        'SELECT * FROM table1 WHERE age BETWEEN 20 AND 30;'
        */
        return "SELECT * FROM " + this.table_name + " WHERE age BETWEEN " + min_age.to_string() + " AND " + max_age.to_string() + ";"
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "SELECT "
        for i in range(0, columns.size()) {
            query += "'" + columns.get(i) + "'"
            if i < columns.size() - 1 {
                query += ", "
            }
        }
        query += " FROM " + table
        match where_condition {
            Some(condition) => {
                query += " WHERE "
                var first = true
                for (key, value) in condition.entries() {
                    if not first {
                        query += " AND "
                    }
                    query += key + "='" + value + "'"
                    first = false
                }
            }
            None => {}
        }
        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        var keys = ArrayList<String>()
        var values = ArrayList<String>()
        for (key, value) in data.entries() {
            keys.add(key)
            values.add("'" + value + "'")
        }
        var query = "INSERT INTO " + table + " ("
        for i in range(0, keys.size()) {
            query += keys.get(i)
            if i < keys.size() - 1 {
                query += ", "
            }
        }
        query += ") VALUES ("
        for i in range(0, values.size()) {
            query += values.get(i)
            if i < values.size() - 1 {
                query += ", "
            }
        }
        query += ")"
        return query
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "DELETE FROM " + table
        match where_condition {
            Some(condition) => {
                query += " WHERE "
                var first = true
                for (key, value) in condition.entries() {
                    if not first {
                        query += " AND "
                    }
                    query += key + "='" + value + "'"
                    first = false
                }
            }
            None => {}
        }
        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "UPDATE " + table + " SET "
        var first = true
        for (key, value) in data.entries() {
            if not first {
                query += ", "
            }
            query += key + "='" + value + "'"
            first = false
        }
        match where_condition {
            Some(condition) => {
                query += " WHERE "
                var first_where = true
                for (key, value) in condition.entries() {
                    if not first_where {
                        query += " AND "
                    }
                    query += key + "='" + value + "'"
                    first_where = false
                }
            }
            None => {}
        }
        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if data.size() == 0 {
            return 0.0
        }
        let sorted = ArrayList<Int64>()
        for item in data {
            sorted.append(item)
        }
        sort(sorted)
        let n = sorted.size()
        if n % 2 == 0 {
            return (sorted[n / 2 - 1] + sorted[n / 2]) as Float64 / 2.0
        } else {
            return sorted[n / 2] as Float64
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if data.size() == 0 {
            return ArrayList<Int64>()
        }
        let freq_map = HashMap<Int64, Int64>()
        for item in data {
            if freq_map.contains(item) {
                freq_map[item] = freq_map[item] + 1
            } else {
                freq_map[item] = 1
            }
        }
        let max_count = ref 0
        for (_, count) in freq_map {
            if count > max_count {
                max_count = count
            }
        }
        let modes = ArrayList<Int64>()
        for (value, count) in freq_map {
            if count == max_count {
                modes.append(value)
            }
        }
        sort(modes)
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if x.size() != y.size() || x.size() == 0 {
            return Option<Float64>.none()
        }
        let n = x.size()
        let x_mean_opt = mean(x)
        let y_mean_opt = mean(y)
        if x_mean_opt.is_none() || y_mean_opt.is_none() {
            return Option<Float64>.none()
        }
        let x_mean = x_mean_opt.unwrap()
        let y_mean = y_mean_opt.unwrap()
        let mut cov = 0.0
        let mut var_x = 0.0
        let mut var_y = 0.0
        for i in 0..n {
            let x_dev = x[i] as Float64 - x_mean
            let y_dev = y[i] as Float64 - y_mean
            cov += x_dev * y_dev
            var_x += x_dev * x_dev
            var_y += y_dev * y_dev
        }
        if var_x == 0.0 || var_y == 0.0 {
            return Option<Float64>.none()
        }
        let corr = cov / (sqrt(var_x) * sqrt(var_y))
        return Option<Float64>.some(corr)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if data.size() == 0 {
            return Option<Float64>.none()
        }
        let mut sum = 0.0
        for item in data {
            sum += item as Float64
        }
        return Option<Float64>.some(sum / data.size() as Float64)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        if data.size() == 0 {
            return ArrayList<ArrayList<Float64>>()
        }
        let rows = data.size()
        let cols = data[0].size()
        for row in data {
            if row.size() != cols {
                // Inconsistent dimensions
                return ArrayList<ArrayList<Float64>>()
            }
        }
        let matrix = ArrayList<ArrayList<Float64>>()
        for i in 0..rows {
            let row = ArrayList<Float64>()
            for j in 0..rows {
                let corr = correlation(data[i], data[j])
                if corr.is_some() {
                    row.append(corr.unwrap())
                } else {
                    row.append(0.0)
                }
            }
            matrix.append(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        if data.size() == 0 {
            return Option<Float64>.none()
        }
        let mean_opt = mean(data)
        if mean_opt.is_none() {
            return Option<Float64>.none()
        }
        let m = mean_opt.unwrap()
        let mut variance = 0.0
        for item in data {
            let diff = item as Float64 - m
            variance += diff * diff
        }
        variance = variance / data.size() as Float64
        return Option<Float64>.some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_opt = mean(data)
        let stdev_opt = standard_deviation(data)
        if mean_opt.is_none() || stdev_opt.is_none() {
            return Option<ArrayList<Float64>>.none()
        }
        let m = mean_opt.unwrap()
        let stdev = stdev_opt.unwrap()
        let z_scores = ArrayList<Float64>()
        if stdev == 0.0 {
            for _ in data {
                z_scores.append(0.0)
            }
        } else {
            for item in data {
                z_scores.append((item as Float64 - m) / stdev)
            }
        }
        return Option<ArrayList<Float64>>.some(z_scores)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs

class Stock <: Equatable<Stock> {

    let name: String
    var price: Float64
    var quantity: Int64

    public init(name: String, price: Float64, quantity: Int64) {
        this.name = name
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Stock): Bool {
        return this.name != that.name || this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Stock): Bool {
        return this.name == that.name && this.price == that.price && this.quantity == that.quantity
    }
}

class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        this.portfolio.append(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        for i in 0..this.portfolio.size() {
            if this.portfolio[i] == stock {
                this.portfolio.remove_at(i)
                return true
            }
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let total_cost = stock.price * (stock.quantity as Float64)
        if this.cash_balance >= total_cost {
            this.cash_balance -= total_cost
            this.add_stock(stock)
            return true
        }
        return false
    }

    public func sell_stock(stock: Stock): Bool {
        for i in 0..this.portfolio.size() {
            let held_stock = this.portfolio[i]
            if held_stock.name == stock.name && held_stock.price == stock.price {
                if held_stock.quantity >= stock.quantity {
                    let revenue = stock.price * (stock.quantity as Float64)
                    this.cash_balance += revenue
                    held_stock.quantity -= stock.quantity
                    if held_stock.quantity == 0 {
                        this.portfolio.remove_at(i)
                    }
                    return true
                }
                return false
            }
        }
        return false
    }

    public func calculate_portfolio_value(): Float64 {
        var total_value = this.cash_balance
        for stock in this.portfolio {
            total_value += stock.price * (stock.quantity as Float64)
        }
        return total_value
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        let summary = ArrayList<HashMap<String, Any>>()
        for stock in this.portfolio {
            let stock_value = stock.price * (stock.quantity as Float64)
            let stock_info = HashMap<String, Any>()
            stock_info["name"] = stock.name
            stock_info["value"] = stock_value
            summary.append(stock_info)
        }
        let total_value = this.calculate_portfolio_value()
        return (total_value, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * (stock.quantity as Float64)
    }
}

import std.math.abs

class Thermostat {

    /*
    The class manages temperature control, including setting and retrieving the target temperature, adjusting the mode, and simulating temperature operation.
    */

    var current_temperature: Float64
    var target_temperature: Float64
    var mode: String

    public init(current_temperature: Float64, target_temperature: Float64, mode: String) {
        /*
        initialize instances of the Thermostat class, including the current temperature, target temperature, and operating mode.
        :param current_temperature: Float64
        :param target_temperature: Float64
        :param mode: String, the work mode
        */
        this.current_temperature = current_temperature
        this.target_temperature = target_temperature
        this.mode = mode
    }

    public func get_target_temperature(): Float64 {
        /*
        Get the target temperature of an instance of the Thermostat class.
        :return this.target_temperature: Float64
        >>> thermostat.get_target_temperature()
        37.5
        */
        return this.target_temperature
    }

    public func set_target_temperature(temperature: Float64): Unit {
        /*
        Set the target temperature
        :param temperature: Float64, the target temperature
        >>> thermostat.set_target_temperature(37.6)
        >>> thermostat.target_temperature
        37.6
        */
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        /*
        Get the current work mode
        :return mode: String, working mode. only ['heat', 'cool']
        */
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        /*
        Get the current work mode
        :param mode: String, working mode. only ['heat', 'cool']
        >>> thermostat.set_mode('cool')
        >>> thermostat.mode
        'cool'
        */
        if mode == "heat" || mode == "cool" {
            this.mode = mode
            return true
        } else {
            return false
        }
    }

    public func auto_set_mode(): Unit {
        /*
        Automatically set the operating mode by comparing with the current temperature and target temperature. If the current temperature is lower than the target temperature, the operating mode is set to 'heat', otherwise it is set to 'cool'.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.auto_set_mode()
        >>> thermostat.mode
        'heat'
        */
        if this.current_temperature < this.target_temperature {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        /*
        Check if there is a conflict between the operating mode and the relationship between the current temperature and the target temperature.
        If there is a conflict, the operating mode will be adjusted automatically.
        :return: true if mode isn't conflict with the relationship between the current temperature and the target temperature, or false otherwise.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.auto_check_conflict()
        false
        >>> thermostat.mode
        'heat'
        */
        let expected_mode = this.current_temperature < this.target_temperature ? "heat" : "cool"
        if this.mode != expected_mode {
            this.mode = expected_mode
            return false
        }
        return true
    }

    public func simulate_operation(): Int64 {
        /*
        simulate the operation of Thermostat. It will automatically start the auto_set_mode method to set the operating mode,
        and then automatically adjust the current temperature according to the operating mode until the target temperature is reached.
        :return time: Int64, the time it took to complete the simulation.
        >>> thermostat = Thermostat(20.4, 37.5, 'cool')
        >>> thermostat.simulate_operation()
        18
        */
        this.auto_set_mode()
        var time: Int64 = 0
        while abs(this.current_temperature - this.target_temperature) > 0.1 {
            if this.mode == "heat" {
                this.current_temperature += 0.5
            } else {
                this.current_temperature -= 0.5
            }
            time += 1
        }
        return time
    }
}

import std.collection.ArrayList

class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..N) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if row < 0 || row >= this.board.size() || col < 0 || col >= this.board.size() {
            return false
        }
        if this.board[row][col] != ' ' {
            return false
        }
        this.board[row][col] = this.current_player
        this.current_player = if this.current_player == 'X' { 'O' } else { 'X' }
        return true
    }

    public func check_winner(): Option<String> {
        let N = this.board.size()
        for i in 0..N {
            if this.board[i][0] != ' ' {
                var win = true
                for j in 1..N {
                    if this.board[i][j] != this.board[i][0] {
                        win = false
                        break
                    }
                }
                if win {
                    return Option.some(this.board[i][0])
                }
            }
        }
        for j in 0..N {
            if this.board[0][j] != ' ' {
                var win = true
                for i in 1..N {
                    if this.board[i][j] != this.board[0][j] {
                        win = false
                        break
                    }
                }
                if win {
                    return Option.some(this.board[0][j])
                }
            }
        }
        if this.board[0][0] != ' ' {
            var win = true
            for i in 1..N {
                if this.board[i][i] != this.board[0][0] {
                    win = false
                    break
                }
            }
            if win {
                return Option.some(this.board[0][0])
            }
        }
        if this.board[0][N - 1] != ' ' {
            var win = true
            for i in 1..N {
                if this.board[i][N - 1 - i] != this.board[0][N - 1] {
                    win = false
                    break
                }
            }
            if win {
                return Option.some(this.board[0][N - 1])
            }
        }
        return Option.none()
    }

    public func is_board_full(): Bool {
        for row in this.board {
            for cell in row {
                if cell == ' ' {
                    return false
                }
            }
        }
        return true
    }
}

import std.time.DateTime
import std.math.round

class TimeUtils {

    /*
    This is a time util class, including getting the current time and date, adding seconds to a datetime, converting between strings and datetime objects, calculating the time difference in minutes, and formatting a datetime object.
    */

    let datetime: DateTime

    public init() {
        /*
        Get the current datetime
        */
        this.datetime = DateTime.now()
    }

    public func get_current_time(): String {
        /*
        Return the current time in the format of 'HH:mm:ss'
        :return: String
        >>> timeutils = TimeUtils()
        >>> timeutils.get_current_time()
        "19:19:22"
        */
        return this.datetime.format("HH:mm:ss")
    }

    public func get_current_date(): String {
        /*
        Return the current date in the format of "yyyy-MM-dd"
        :return: String
        >>> timeutils.get_current_date()
        "2023-06-14"
        */
        return this.datetime.format("yyyy-MM-dd")
    }

    public func add_seconds(seconds: Int64): String {
        /*
        Add the specified number of seconds to the current time
        :param seconds: Int64, number of seconds to add
        :return: String, time after adding the specified number of seconds in the format 'HH:mm:ss'
        >>> timeutils.add_seconds(600)
        "19:29:22"
        */
        let new_datetime = this.datetime.plus_seconds(seconds)
        return new_datetime.format("HH:mm:ss")
    }

    public func string_to_datetime(string: String): DateTime {
        /*
        Convert the time string to a datetime instance
        :param string: String, string before converting format
        :return: DateTime
        >>> timeutils.string_to_datetime("2001-07-18 01:01:01")
        2001-07-18 01:01:01
        */
        return DateTime.parse(string, "yyyy-MM-dd HH:mm:ss")
    }

    public func datetime_to_string(datetime: DateTime): String {
        /*
        Convert a datetime instance to a string
        :param datetime: the DatetTime instance to convert
        :return: String, converted time string
        >>> timeutils.datetime_to_string(timeutils.datetime)
        "2023-06-14 19:30:03"
        */
        return datetime.format("yyyy-MM-dd HH:mm:ss")
    }

    public func get_minutes(string_time1: String, string_time2: String): Int64 {
        /*
        Calculate how many minutes have passed between two times, and round the results to the nearest
        :return: Int64, the number of minutes between two times, rounded off
        >>> timeutils.get_minutes("2001-07-18 01:01:01", "2001-07-18 02:01:01")
        60
        */
        let dt1 = DateTime.parse(string_time1, "yyyy-MM-dd HH:mm:ss")
        let dt2 = DateTime.parse(string_time2, "yyyy-MM-dd HH:mm:ss")
        let diff_seconds = (dt2.timestamp() - dt1.timestamp()).abs()
        let diff_minutes = diff_seconds / 60.0
        return round(diff_minutes) as Int64
    }

    public func get_format_time(year: Int64, month: Int64, day: Int64, hour: Int64, minute: Int64, second: Int64): String {
        /*
        get format time
        :param year: Int64
        :param month: Int64
        :param day: Int64
        :param hour: Int64
        :param minute: Int64
        :param second: Int64
        :return: formatted time string
        >>> timeutils.get_format_time(2001, 7, 18, 1, 1, 1)
        "2001-07-18 01:01:01"
        */
        let dt = DateTime.create(year, month, day, hour, minute, second)
        return dt.format("yyyy-MM-dd HH:mm:ss")
    }
}

import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    /*
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    */

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let rad = x * PI / 180.0
        return taylor(rad, 50)
    }

    public func factorial(a: Int64): Decimal {
        if a == 0 || a == 1 {
            return Decimal(1)
        }
        var result = Decimal(1)
        for i in 2..a+1 {
            result = result * Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var result = 0.0
        for i in 0..n {
            let numerator = pow(-1, i) * pow(x, 2 * i)
            let denominator = Float64(factorial(2 * i).toFloat64())
            result += numerator / denominator
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        let rad = x * PI / 180.0
        var result = 0.0
        for i in 0..50 {
            let numerator = pow(-1, i) * pow(rad, 2 * i + 1)
            let denominator = Float64(factorial(2 * i + 1).toFloat64())
            result += numerator / denominator
        }
        return result
    }

    public func tan(x: Float64): Option<Float64> {
        let cosVal = cos(x)
        if abs(cosVal - 0.0) < 0.000001 {
            return None
        }
        return Some(sin(x) / cosVal)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.random.Random
import std.convert.Parsable

class Parser {

    /*
    This class is used to parse the expression to get the answer
    params: expression, String
    >>> parser = Parser("4+3+6+6")
    >>> parser.parse()
    19
    */

    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {

    /*
    This ia a game of twenty-four points, which provides to generate four numbers and check whether player's expression is equal to 24.
    */

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        /*
        Generate random numbers between 1 and 9 for the cards.
        */
        this.nums.clear()
        let rand = Random()
        for _ in 0..4 {
            this.nums.add(rand.nextInt(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        /*
        Get a list of four random numbers between 1 and 9 representing the player's cards.
        :return: ArrayList<Int64>, representing the player's cards
        >>> game = TwentyFourPointGame()
        >>> game.get_my_cards()
        */
        this._generate_cards()
        return this.nums.clone()
    }

    public func answer(expression: String): Bool {
        /*
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: String, mathematical expression using the cards
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> game.nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.answer(ans)
        true
        */
        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        /*
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: String, mathematical expression
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.evaluate_expression(ans)
        true
        */
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch {
            return false
        }
    }
}

import std.collection.HashMap

class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let schema_end = this.url.find("://")
        if schema_end.is_none() {
            return Option::none()
        }
        let end = schema_end.unwrap()
        return Option::some(this.url.slice(0, end))
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let schema_end = this.url.find("://")
        if schema_end.is_none() {
            return Option::none()
        }
        let start = schema_end.unwrap() + 3
        let rest = this.url.slice(start)
        let path_index = rest.find("/") or_else { rest.len() }
        let query_index = rest.find("?") or_else { rest.len() }
        let fragment_index = rest.find("#") or_else { rest.len() }
        let end = min(min(path_index, query_index), fragment_index)
        if end == 0 {
            return Option::none()
        }
        return Option::some(rest.slice(0, end))
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let schema_end = this.url.find("://")
        let start = schema_end.map(|idx| idx + 3).or_else { 0 }
        let rest = this.url.slice(start)
        let host_end = this.find_host_end(rest)
        if host_end >= rest.len() {
            return Option::none()
        }
        return Option::some(rest.slice(host_end))
    }

    private func find_host_end(s: String): Int {
        let path_index = s.find("/") or_else { s.len() }
        let query_index = s.find("?") or_else { s.len() }
        let fragment_index = s.find("#") or_else { s.len() }
        min(min(path_index, query_index), fragment_index)
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let query_start = this.url.find("?")
        if query_start.is_none() {
            return Option::none()
        }
        let start = query_start.unwrap() + 1
        let fragment_index = this.url.find("#").or_else { this.url.len() }
        let query_str = this.url.slice(start, fragment_index)
        if query_str.len() == 0 {
            return Option::none()
        }
        let params = HashMap::new()
        let pairs = query_str.split("&")
        for pair in pairs {
            let kv = pair.split("=")
            if kv.len() == 2 {
                params.insert(kv[0], kv[1])
            }
        }
        return Option::some(params)
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let fragment_start = this.url.find("#")
        if fragment_start.is_none() {
            return Option::none()
        }
        let start = fragment_start.unwrap() + 1
        return Option::some(this.url.slice(start))
    }
}

import std.collection.ArrayList

class UrlPath {

    /*
    The  class is a utility for encapsulating and manipulating the path component of a URL, including adding nodes, parsing path strings, and building path strings with optional encoding.
    */

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        /*
        Initializes the UrlPath object with an empty list of segments and a flag indicating the presence of an end tag.
        */
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        /*
        Adds a segment to the list of segments in the UrlPath.
        :param segment: String, the segment to add.
        >>> url_path = UrlPath()
        >>> url_path.add('foo')
        >>> url_path.add('bar')

        url_path.segments = ['foo', 'bar']
        */
        this.segments.append(segment)
    }

    public func parse(path: String): Unit {
        /*
        Parses a given path string and populates the list of segments in the UrlPath.
        :param path: String, the path string to parse.
        >>> url_path = UrlPath()
        >>> url_path.parse('/foo/bar/')

        url_path.segments = ['foo', 'bar']
        */
        let fixed_path = UrlPath.fix_path(path)
        if fixed_path == "" {
            return
        }
        let parts = fixed_path.split('/')
        for part in parts {
            if part != "" {
                this.segments.append(part)
            }
        }
        this.with_end_tag = path.endsWith("/")
    }

    public static func fix_path(path: String): String {
        /*
        Fixes the given path string by removing leading and trailing slashes.
        :param path: String, the path string to fix.
        :return: String, the fixed path string.
        >>> url_path = UrlPath()
        >>> url_path.fix_path('/foo/bar/')
        'foo/bar'

        */
        let start = path.startsWith("/") ? 1 : 0
        let end = path.endsWith("/") ? path.length() - 1 : path.length()
        return path.substring(start, end)
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        var dot_product: Float64 = 0.0
        var norm1: Float64 = 0.0
        var norm2: Float64 = 0.0

        for i in range(vector_1.size()) {
            dot_product += vector_1[i] * vector_2[i]
            norm1 += pow(vector_1[i], 2)
            norm2 += pow(vector_2[i], 2)
        }

        if norm1 == 0.0 || norm2 == 0.0 {
            return 0.0
        }

        return dot_product / (sqrt(norm1) * sqrt(norm2))
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        var result: ArrayList<Float64> = ArrayList<Float64>()

        for vector in vectors_all {
            result.append(similarity(vector_1, vector))
        }

        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        var avg_vector_1: ArrayList<Float64> = ArrayList<Float64>()
        var avg_vector_2: ArrayList<Float64> = ArrayList<Float64>()

        if vector_list_1.size() == 0 || vector_list_2.size() == 0 {
            return 0.0
        }

        for i in range(vector_list_1[0].size()) {
            avg_vector_1.append(0.0)
            avg_vector_2.append(0.0)
        }

        for vector in vector_list_1 {
            for i in range(vector.size()) {
                avg_vector_1[i] += vector[i]
            }
        }

        for vector in vector_list_2 {
            for i in range(vector.size()) {
                avg_vector_2[i] += vector[i]
            }
        }

        for i in range(avg_vector_1.size()) {
            avg_vector_1[i] /= vector_list_1.size()
            avg_vector_2[i] /= vector_list_2.size()
        }

        return similarity(avg_vector_1, avg_vector_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        var result: HashMap<String, Float64> = HashMap<String, Float64>()

        for entry in number_dict.entries() {
            var key: String = entry.key
            var count: Float64 = entry.value
            var weight: Float64 = log((total_num + 1) / (count + 1))
            result.put(key, weight)
        }

        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Product <: Equatable<Product> {

    let price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class VendingMachine {

    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        let product = Product(price: price, quantity: quantity)
        this.inventory.insert(key: item_name, value: product)
    }

    public func insert_coin(amount: Float64): Float64 {
        this.balance = this.balance + amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        if !this.inventory.contains(key: item_name) {
            return None()
        }
        let product = this.inventory.get(key: item_name).unwrap()
        if product.quantity <= 0 {
            return None()
        }
        if this.balance < product.price {
            return None()
        }
        product.quantity = product.quantity - 1
        this.balance = this.balance - product.price
        return Some(this.balance)
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        if !this.inventory.contains(key: item_name) {
            return false
        }
        let product = this.inventory.get(key: item_name).unwrap()
        product.quantity = product.quantity + quantity
        return true
    }

    public func display_items(): Option<String> {
        if this.inventory.size() == 0 {
            return None()
        }
        let result = ArrayList<String>()
        for (name, product) in this.inventory {
            let item_str = "${name} - $${product.price} [${product.quantity}]"
            result.append(item_str)
        }
        return Some(result.join(separator: "\n"))
    }
}

